  $('secondMediaInput').addEventListener('change',e=>{state.secondFile=e.target.files[0]||null;if(state.secondFile){const err=validateLocal(state.secondFile,state.kind);setStatus('toolStatus',err||`Second file selected: ${state.secondFile.name}`,!err);}});
  function xhrUpload(url,form,onProgress){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();state.uploadXhr=x;x.open('POST',url);x.withCredentials=true;x.upload.onprogress=e=>{if(e.lengthComputable)onProgress(e.loaded,e.total);};x.onload=()=>{let data;try{data=JSON.parse(x.responseText);}catch{data={};}if(x.status>=200&&x.status<300)resolve({data,xhr:x});else reject(new Error(data.error||`Upload failed (${x.status}).`));};x.onerror=()=>reject(new Error('Network error during upload.'));x.onabort=()=>reject(new Error('Upload cancelled.'));state.uploadStartedAt=Date.now();x.send(form);});}
