  async function pollJob(id){const start=Date.now();let lastPct=0,netFails=0;for(let i=0;i<900;i++){await new Promise(r=>setTimeout(r,2000));let d;try{d=await api(`/api/jobs/${encodeURIComponent(id)}`);netFails=0;}catch(err){if(err instanceof TypeError&&++netFails<=10){$('processingLog').textContent='Server is busy or restarting. Retrying…';continue;}throw err;}const pct=Math.max(lastPct,Math.min(99,Number(d.progress||0)));lastPct=pct;const elapsed=Math.max(1,Math.floor((Date.now()-start)/1000));let remaining=`~${Math.ceil(Number(d.estimateSeconds||0))} sec (server estimate)`;if(pct>=2){const total=elapsed/(pct/100);remaining=`~${Math.max(0,Math.ceil(total-elapsed))} sec (progress-based)`;}$('remainingTime').textContent=remaining;processingProgress(pct,d.status==='processing'?'Processing':d.status, d.status==='processing'?`${d.progressLabel||'FFmpeg render progress'}: ${pct.toFixed(1)}% · Estimated remaining time is approximate and may change with server load.`:d.error||'Finalizing output…');if(d.status==='completed'){finishProcessing();$('remainingTime').textContent='Complete';return d;}if(d.status==='failed')throw new Error(d.error||'Media processing failed.');if(d.status==='cancelled')throw new Error(d.error||'Job cancelled.');}throw new Error('Processing is taking longer than the current 30-minute wait window. Check your job again or contact Help.');}
  function showResult(r){finishProcessing();if(!String(r.url||'').startsWith('blob:'))state.resultBlob=null;showPage(5);$('resultTitle').textContent=r.title;$('resultMeta').textContent=r.message;$('resultBody').innerHTML='';$('resultPreview').innerHTML='';$('downloadResult').classList.add('hidden');if(r.kind==='report'){const pre=document.createElement('pre');pre.textContent=JSON.stringify(r.data,null,2);$('resultBody').append(pre);const blob=new Blob([JSON.stringify(r.data,null,2)],{type:'application/json'});state.downloadUrl=URL.createObjectURL(blob);state.downloadName='vidora-report.json';$('downloadResult').classList.remove('hidden');}else{const previewType=String(state.tool||'').startsWith('photo-')?'image':(['audio-enhance','audio-extract','audio-fingerprint'].includes(state.tool)?'audio':state.kind==='audio'?'audio':'video');const preview=document.createElement(previewType==='image'?'img':previewType);if(previewType==='image')preview.alt='Enhanced photo preview';else{preview.controls=true;preview.preload='metadata';}preview.src=r.url;$('resultPreview').append(preview);const a=document.createElement('a');a.className='download-anchor';a.href=r.url;a.textContent='Download processed file ↓';if(r.name){a.addEventListener('click',e=>{e.preventDefault();downloadFile(r.url,r.name);});}else a.download=r.name||'vidora-result';$('resultBody').append(a);state.downloadUrl=r.url;state.downloadName=r.name||'vidora-result';$('downloadResult').classList.remove('hidden');if(previewType==='image'&&state.beforeUrl){const cmp=makeCompare(state.beforeUrl,r.url);if(cmp){$('resultPreview').innerHTML='';$('resultPreview').append(cmp);}}}
    prepareShare(r.kind!=='report'); $('resultBack').onclick=()=>{if(r.backOnly){showPage(2);resetMedia();}else showPage(2);};$('downloadResult').onclick=()=>downloadFile(state.downloadUrl,state.downloadName);}
  async function downloadFile(url,name){try{let object;if(url.startsWith('blob:'))object=url;else{const r=await fetch(url,{credentials:'same-origin'});if(!r.ok)throw new Error('Download is not available.');object=URL.createObjectURL(await r.blob());}const a=document.createElement('a');a.href=object;a.download=name||'vidora-result';document.body.append(a);a.click();a.remove();if(!url.startsWith('blob:'))setTimeout(()=>URL.revokeObjectURL(object),30000);}catch(e){toast(e.message);}}
  $('startTool').addEventListener('click',runSelectedTool);$('cancelProcess').addEventListener('click',async()=>{if(state.jobId){try{await api(`/api/jobs/${encodeURIComponent(state.jobId)}/cancel`,{method:'POST'});}catch{}}if(state.uploadXhr&&state.uploadXhr.readyState!==4)state.uploadXhr.abort();finishProcessing();showPage(2);});$('resultBack').addEventListener('click',()=>showPage(2));
