  async function loadComments(){try{const d=await api('/api/community/public');const htmlTargets=[$('publicComments'),$('commentsPage2'),$('commentsPage3')].filter(Boolean);htmlTargets.forEach(target=>{target.innerHTML='';if(!d.comments?.length){target.textContent='No public comments yet.';return;}d.comments.slice(0,8).forEach(c=>{const item=document.createElement('div');item.className='comment-item';const b=document.createElement('b');b.textContent=c.name||'Creator';const p=document.createElement('p');p.textContent=c.body;item.append(b,p);target.append(item);});});}catch{['publicComments','commentsPage2','commentsPage3'].forEach(id=>{if($(id))$(id).textContent='Community comments are temporarily unavailable.';});}}
  async function postComment(inputId){if(!state.user){toast('Sign in to post a comment.');showPage(1);return;}const body=$(inputId).value.trim();if(body.length<3){toast('Write at least 3 characters.');return;}try{const d=await api('/api/community/comments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body,kind:'feedback'})});$(inputId).value='';toast(d.message||'Your comment was submitted for review.');loadMyReports();}catch(e){toast(e.message);}}
